/// <summary>
/// Creates a new <c>AAXMRPRunCompletedBusinessEventContract</c> from the specified plan ID.
/// </summary>
/// <param name="_planId">The plan ID value.</param>
/// <returns>A new populated instance of <c>AAXMRPRunCompletedBusinessEventContract</c>.</returns>
public static AAXMRPRunCompletedBusinessEventContract construct(str _planId)
{
    var contract = new AAXMRPRunCompletedBusinessEventContract();
    contract.parmLegalEntity(curExt());
    contract.parmPlanId(_planId);

    return contract;
}

/// <summary>
/// Private constructor. Use static factory methods to create instances.
/// </summary>
private void new()
{
}

/// <summary>
/// Gets or sets the legal entity.
/// </summary>
/// <param name="_legalEntity">The legal entity value.</param>
/// <returns>The legal entity value.</returns>
[DataMember('legalEntity'), BusinessEventsDataMember("Legal Entity")]
public DataAreaId parmLegalEntity(DataAreaId _legalEntity = legalEntity)
{
    legalEntity = _legalEntity;

    return legalEntity;
}

/// <summary>
/// Gets or sets the plan ID.
/// </summary>
/// <param name="_planId">The plan ID value.</param>
/// <returns>The plan ID value.</returns>
[DataMember('planId'), BusinessEventsDataMember("Plan ID")]
public str parmPlanId(str _planId = planId)
{
    planId = _planId;

    return planId;
}
